import re

EMAIL = re.compile(r"[\w.%+-]+@(?:[A-Za-z0-9-]+\.)+[A-Za-z]{2,}")
DATE = re.compile(r"\b(\d{1,2})/(\d{1,2})/(\d{4})\b")
LOG = re.compile(r"(?P<date>\d{4}-\d{2}-\d{2}) (?P<time>\d{2}:\d{2}:\d{2}) (?P<level>[A-Z]+) (?P<message>.+)")


def find_emails(text):
    return sorted({m.lower() for m in EMAIL.findall(text)})


def to_iso_dates(text):
    return DATE.sub(lambda m: f"{m.group(3)}-{int(m.group(2)):02}-{int(m.group(1)):02}", text)


def is_hex_colour(text):
    return re.fullmatch(r"#(?:[0-9a-fA-F]{3}|[0-9a-fA-F]{6})", text) is not None


def parse_log(line):
    m = LOG.fullmatch(line.strip())
    return m.groupdict() if m else None

