@test("emails")
def _():
    text = "Write to Ada@Example.org or grace.hopper+navy@mail.co.uk; not to bob@ or @x.com. ada@example.org again."
    check_eq(find_emails(text), ["ada@example.org", "grace.hopper+navy@mail.co.uk"])
    check_eq(find_emails("nothing here"), [])

@test("dates")
def _():
    check_eq(to_iso_dates("Due 15/11/2026, paid 5/1/2027."), "Due 2026-11-15, paid 2027-01-05.")
    check_eq(to_iso_dates("version 1/2 and 2026-11-15"), "version 1/2 and 2026-11-15")

@test("colours")
def _():
    for good in ["#fff", "#1a2B3c", "#000000"]:
        check(is_hex_colour(good), good)
    for bad in ["fff", "#ffff", "#12345g", "#1234567", " #fff", "#fff "]:
        check(not is_hex_colour(bad), bad)

@test("log lines")
def _():
    check_eq(parse_log("2026-11-15 10:42:07 ERROR disk full"), {"date": "2026-11-15", "time": "10:42:07", "level": "ERROR", "message": "disk full"})
    check_eq(parse_log("2026-11-15 10:42:07 error disk full"), None)
    check_eq(parse_log("2026-11-15 10:42 INFO started"), None)
    check_eq(parse_log("2026-11-15 10:42:07 INFO"), None)

